def comps(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); reg=[(r,c)]
                while st:
                    x,y=st.pop()
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            n=(x+dx,y+dy)
                            if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]!=bg and n not in seen:
                                seen.add(n); st.append(n); reg.append(n)
                out.append(reg)
    return out
def norm(cells):
    mr=min(r for r,_ in cells); mc=min(c for _,c in cells)
    return tuple(sorted((r-mr,c-mc) for r,c in cells))
def syms(sh):
    hh=max(r for r,_ in sh)+1; ww=max(c for _,c in sh)+1
    def rot(s): return tuple(sorted((c,hh-1-r) for r,c in s))
    res={'id':sh}; cur=sh
    for _ in range(3):
        cur=rot(cur); res[f'r{(_)}']:cur
    res.update({'vf':tuple(sorted((hh-1-r,c) for r,c in sh)),
                'hf':tuple(sorted((r,ww-1-c) for r,c in sh)),
                'rv':tuple(sorted((hh-1-r,ww-1-c) for r,c in sh))})
    return res
