            nsh=norm(s); V=syms(nsh)
            # find translation maximizing overlap of placed cells onto bg positions; prefer closest anchor
            best=None
            for name,v in V.items():
                for dr in range(-H,H+1):
                    for dc in range(-W,W+1):
                        t=[(rr+dr,cc+dc) for rr,cc in v]
                        if any(r<0 or r>=H or c<0 or c>=W for r,c in t): continue
                        ok=True; cnt=0
                        for r,c in t:
